import{_ as d,o as e,c as a,a2 as o}from"./chunks/framework.BUS5y9ZA.js";const s=JSON.parse('{"title":"올바름 인력관리시스템 운영 매뉴얼","description":"","frontmatter":{},"headers":[],"relativePath":"operations-manual.md","filePath":"operations-manual.md"}'),r={name:"operations-manual.md"};function l(i,t,c,h,n,b){return e(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="올바름-인력관리시스템-운영-매뉴얼" tabindex="-1">올바름 인력관리시스템 운영 매뉴얼 <a class="header-anchor" href="#올바름-인력관리시스템-운영-매뉴얼" aria-label="Permalink to &quot;올바름 인력관리시스템 운영 매뉴얼&quot;">​</a></h1><h2 id="_1-운영-직군" tabindex="-1">1. 운영 직군 <a class="header-anchor" href="#_1-운영-직군" aria-label="Permalink to &quot;1. 운영 직군&quot;">​</a></h2><table tabindex="0"><thead><tr><th>직군</th><th>주요 업무</th></tr></thead><tbody><tr><td>관리자</td><td>직원·근무지·배정·교육·점검·리포트·계정 관리</td></tr><tr><td>시스템 운영 담당자</td><td>배포, 환경변수, DB, 로그, 장애 대응, 백업 관리</td></tr><tr><td>현장 근무자</td><td>출퇴근, 교육 이수, 점검, 특이사항 보고</td></tr></tbody></table><h2 id="_2-일상-운영" tabindex="-1">2. 일상 운영 <a class="header-anchor" href="#_2-일상-운영" aria-label="Permalink to &quot;2. 일상 운영&quot;">​</a></h2><h3 id="_2-1-직원과-배정" tabindex="-1">2.1 직원과 배정 <a class="header-anchor" href="#_2-1-직원과-배정" aria-label="Permalink to &quot;2.1 직원과 배정&quot;">​</a></h3><ol><li>직원 등록 시 이름, 연락처, 직무를 확인한다.</li><li>퇴직자는 삭제보다 퇴직 상태 처리를 우선한다.</li><li>근무지 주소와 GPS 좌표, 출근 인정 반경을 확인한다.</li><li>직원별 배정 시작일과 종료일이 겹치지 않게 등록한다.</li></ol><h4 id="_2-1-1-배정등록-저장-시-근무일·휴무일·출퇴근-예정시각-기준" tabindex="-1">2.1.1 배정등록 저장 시 근무일·휴무일·출퇴근 예정시각 기준 <a class="header-anchor" href="#_2-1-1-배정등록-저장-시-근무일·휴무일·출퇴근-예정시각-기준" aria-label="Permalink to &quot;2.1.1 배정등록 저장 시 근무일·휴무일·출퇴근 예정시각 기준&quot;">​</a></h4><p>배정등록을 저장하면 선택한 직원의 근무형태와 출퇴근 시간을 기준으로 배정기간의 날짜별 예정시각이 생성된다. 배정등록 화면에 표시되는 출근·퇴근 시간은 직원 정보에 설정된 값을 기본으로 하며, 저장 시 배정의 기준 시간으로 함께 보관한다. 시간이 별도로 전달되지 않는 경우에는 직원 정보의 출퇴근 시간을 사용한다. 날짜별 예정시각은 한국 시간 기준으로 관리한다.</p><table tabindex="0"><thead><tr><th>근무형태</th><th>배정 저장 시 적용 기준</th></tr></thead><tbody><tr><td>일반근무(0)</td><td>배정기간의 모든 날짜에 출근 예정시각과 퇴근 예정시각을 생성한다. 토·일 및 공휴일을 자동 휴무로 처리하지 않는다.</td></tr><tr><td>격일근무(1)</td><td>배정 시작일부터 하루씩 교대한다. 짝수 번째 날짜(시작일 포함)에만 근무기록을 만들고, 해당 행에 출근 예정시각과 다음 날 퇴근 예정시각을 함께 저장한다. 홀수 번째 날짜에는 별도 근무기록을 만들지 않는다.</td></tr><tr><td>야간근무(2)</td><td>토요일·일요일 또는 공휴일 관리에서 <code>선택=Y</code>인 날짜를 자동 휴무일로 등록한다. 출근일에 한 건을 생성하고 다음 날 퇴근 예정시각을 같은 자료에 함께 저장한다. 휴무일에는 출근 예정시각을 만들지 않으며, 퇴근 예정시각만을 위한 별도 자료는 만들지 않는다.</td></tr></tbody></table><p>야간근무의 휴무일 판단은 공휴일 API에서 내려온 날짜 자체가 아니라 공휴일 관리 목록에서 <code>선택</code> 값이 <code>Y</code>인 날짜를 기준으로 한다. 공휴일이지만 <code>N</code>으로 저장된 날짜는 자동 휴무 대상이 아니다. 수동 휴무일 지정은 <strong>근무지배정 상세</strong> 화면의 휴무일 캘린더에서 근무기간 안의 날짜를 선택해 저장하며, 저장된 날짜에는 근무자의 출근을 허용하지 않는다.</p><p>출퇴근 예정시각은 직원·근무일별 통합 테이블인 <code>work_record</code>의 <code>intime</code>, <code>outtime</code>에 저장되며, 실제 출퇴근 시각(<code>work_intime</code>, <code>work_outtime</code>)과 함께 출결 등록·근태 판정의 기준으로 사용한다. 배정 저장 후 <strong>근무지배정 상세</strong> 화면의 달력에서 날짜별 출근·퇴근 예정시각과 휴무일 표시를 확인한다.</p><h4 id="_2-1-2-관리자-상세-화면-명칭" tabindex="-1">2.1.2 관리자 상세 화면 명칭 <a class="header-anchor" href="#_2-1-2-관리자-상세-화면-명칭" aria-label="Permalink to &quot;2.1.2 관리자 상세 화면 명칭&quot;">​</a></h4><p>목록에서 자료를 선택해 확인·수정하는 화면은 다음 명칭으로 표시한다.</p><table tabindex="0"><thead><tr><th>대상</th><th>화면 제목</th></tr></thead><tbody><tr><td>직원</td><td>직원 상세</td></tr><tr><td>근무지</td><td>근무지 상세</td></tr><tr><td>근무지 배정</td><td>근무지배정 상세</td></tr><tr><td>교육자료</td><td>교육자료 상세</td></tr><tr><td>근태 기록</td><td>근태 상세</td></tr><tr><td>시스템 설정</td><td>시스템설정 상세</td></tr></tbody></table><p>따라서 배정의 날짜별 예정시각과 휴무일을 확인할 때는 <strong>근무지배정 상세</strong> 화면을 사용한다.</p><h3 id="_2-2-근태" tabindex="-1">2.2 근태 <a class="header-anchor" href="#_2-2-근태" aria-label="Permalink to &quot;2.2 근태&quot;">​</a></h3><ul><li>대시보드에서 당일 출근·결근·지각 현황을 확인한다.</li><li>근태 리포트의 직원명·연도 조건으로 이력을 조회한다.</li><li>GPS 오류 신고 시 기기 위치 권한, 당일 배정, 근무지 좌표와 반경을 순서대로 점검한다.</li></ul><h4 id="_2-2-1-대시보드-출근현황-카드의-출근·지각·결근·대기-집계-기준" tabindex="-1">2.2.1 대시보드 출근현황 카드의 출근·지각·결근·대기 집계 기준 <a class="header-anchor" href="#_2-2-1-대시보드-출근현황-카드의-출근·지각·결근·대기-집계-기준" aria-label="Permalink to &quot;2.2.1 대시보드 출근현황 카드의 출근·지각·결근·대기 집계 기준&quot;">​</a></h4><p>대시보드 첫 번째 <strong>출근현황</strong> 카드의 분모는 현재 재직 직원 전체가 아니다. <code>work_record</code>에서 오늘 날짜(<code>work_date</code>)의 출근 예정시각(<code>intime</code>)이 있는 재직 직원만 집계하며, 직원 ID 기준으로 중복을 제거한다.</p><table tabindex="0"><thead><tr><th>카드 항목</th><th>산출 기준</th></tr></thead><tbody><tr><td>출근</td><td>오늘 출근 예정인 재직 직원 중 예정 출근시각과 같거나 이르게 출근한 직원 수</td></tr><tr><td>지각</td><td>오늘 출근 예정인 재직 직원 중 예정 출근시각보다 늦게 출근한 직원 수</td></tr><tr><td>결근</td><td>출근 예정시각이 현재 시각보다 이전이고, 해당 직원의 오늘 출근 근태자료가 없는 재직 직원 수</td></tr><tr><td>대기</td><td>출근 예정시각이 현재 시각과 같거나 이후이고, 해당 직원의 오늘 출근 근태자료가 없는 재직 직원 수</td></tr><tr><td>합계 기준</td><td><code>출근 + 지각 + 결근 + 대기</code>는 오늘 출근 예정인 재직 직원 수와 일치한다. 직원 ID 기준으로 한 번만 집계한다.</td></tr></tbody></table><p>따라서 카드에는 <code>출근 X 지각 Y 결근Z 대기 W</code> 형식으로 표시된다. 예를 들어 <code>출근 1 지각 1 결근1 대기 1</code>은 정시 출근 1명, 지각 1명, 예정시각이 지난 결근 1명, 아직 예정시각 전이라 대기 중인 직원 1명이라는 뜻이다. 휴무일 등으로 해당 날짜의 <code>intime</code>이 없는 배정은 집계하지 않는다.</p><p>카드의 <code>출근</code>은 퇴근 여부와 관계없이 예정시각 이내 출근자료가 있는 인원을 뜻한다. <code>현재 출근</code> 카드의 미퇴근 인원과는 다른 지표다. 대기·결근·지각·출근은 서로 중복하지 않도록 직원별로 하나의 상태만 부여하며, 이 기준은 직원관리 화면의 재직 직원 수 및 최근 30일 추이 차트의 전체 재직 직원 기준과 다를 수 있다.</p><h4 id="_2-2-2-근태관리의-지각-판정-기준" tabindex="-1">2.2.2 근태관리의 <code>지각</code> 판정 기준 <a class="header-anchor" href="#_2-2-2-근태관리의-지각-판정-기준" aria-label="Permalink to &quot;2.2.2 근태관리의 `지각` 판정 기준&quot;">​</a></h4><p>근태관리 목록은 다음 조건을 모두 만족하는 배정의 예정 출근시각과 실제 출근일시를 비교한다.</p><ol><li>같은 직원이다.</li><li>같은 근무지이다.</li><li>같은 근무일이다.</li><li>해당 날짜의 배정별 예정 출근시각(<code>intime</code>)이 존재한다.</li></ol><p>실제 출근일시가 예정 출근시각보다 늦으면 목록의 상태에 <code>지각</code>을 표시한다. 예정시각과 같거나 이르면 <code>지각</code>으로 표시하지 않는다. 예정 출근시각이 없는 휴무일, 배정과 일치하지 않는 근태기록, 출근일시가 없는 기록은 지각으로 판정하지 않는다. 근태기록을 수정한 경우 다음 목록 조회에서 수정된 출근일시를 기준으로 다시 판정하며, 엑셀 다운로드에도 동일한 상태가 포함된다.</p><h4 id="_2-2-3-출근현황-목록의-상태-표시" tabindex="-1">2.2.3 출근현황 목록의 상태 표시 <a class="header-anchor" href="#_2-2-3-출근현황-목록의-상태-표시" aria-label="Permalink to &quot;2.2.3 출근현황 목록의 상태 표시&quot;">​</a></h4><p><strong>출근현황</strong> 화면은 날짜를 기준으로 <code>work_record</code>에 출근 예정시각(<code>intime</code>)이 있는 재직 직원만 목록에 표시한다. 목록의 <code>출근시각</code>은 같은 행의 실제 출근시각(<code>work_intime</code>)이며, 자료가 없으면 <code>-</code>로 표시한다.</p><table tabindex="0"><thead><tr><th>상태</th><th>표시 기준</th></tr></thead><tbody><tr><td>출근</td><td>실제 출근일시가 예정 출근시각과 같거나 이른 경우</td></tr><tr><td>지각</td><td>실제 출근일시가 예정 출근시각보다 늦은 경우</td></tr><tr><td>대기</td><td>출근 근태자료가 없고 출근 예정시각이 현재 시각과 같거나 이후인 경우</td></tr><tr><td>결근</td><td>출근 근태자료가 없고 출근 예정시각이 현재 시각보다 이전인 경우. 기존 <code>미출근</code> 표기를 <code>결근</code>으로 변경했다.</td></tr></tbody></table><p>목록은 출근 예정시각이 빠른 순서로 정렬하며, 같은 시각에는 직원 이름순으로 표시한다. 목록의 <code>대기</code>·<code>결근</code> 표시는 출근자료 유무와 현재 시각을 함께 반영하며, 대시보드 카드의 결근 수는 현재 시각이 예정 출근시각을 지났는지까지 확인해 집계한다.</p><h4 id="_2-2-4-근무자-홈의-근무일·시간-표시-및-출퇴근-기준" tabindex="-1">2.2.4 근무자 홈의 근무일·시간 표시 및 출퇴근 기준 <a class="header-anchor" href="#_2-2-4-근무자-홈의-근무일·시간-표시-및-출퇴근-기준" aria-label="Permalink to &quot;2.2.4 근무자 홈의 근무일·시간 표시 및 출퇴근 기준&quot;">​</a></h4><p>근무자 홈(<code>/guard/main</code>)의 <code>오늘 근무</code> 카드와 출퇴근 동작은 한국시간 기준으로 조회한 해당 근무자의 <code>work_record</code>를 기준으로 한다. 조회 대상은 <code>work_date</code>가 오늘인 기록과 예정 퇴근일시(<code>outtime</code>)의 한국 날짜가 오늘인 기록이다. 조회 범위에는 근무자의 모든 근무지가 포함된다. 자정을 넘기는 근무는 퇴근 예정일이 오늘이어도 근무일(<code>work_date</code>)을 날짜로 표시한다.</p><table tabindex="0"><thead><tr><th>카드 항목</th><th>표시 기준</th></tr></thead><tbody><tr><td>근무 없음</td><td>조회 결과가 없으면 날짜 위치에 <code>오늘 근무가 없습니다.</code>를 표시하고 시간과 근태 상태를 숨긴다. 출퇴근, 특이사항, 순찰, 점검 진입점을 비활성화한다. 안전교육과 근무정보 메뉴는 사용할 수 있다.</td></tr><tr><td>근무일</td><td>선택된 기록의 <code>work_date</code>를 <code>MM/DD (요일)</code> 형식으로 표시한다. 예: <code>10/28 (금)</code></td></tr><tr><td>예정 시간</td><td>선택된 기록의 예정 <code>intime</code>과 <code>outtime</code>을 한국시간 12시간 형식으로 표시한다. 예: <code>10:00 PM - 6:00 AM</code>. 실제 처리시각이나 배정의 기본 시간으로 대체하지 않는다.</td></tr><tr><td>출근하기</td><td>선택된 기록에 실제 출근시각(<code>work_intime</code>)이 없고 실제 퇴근시각(<code>work_outtime</code>)도 없으면 표시한다. 출근 요청은 선택된 <code>work_date</code>의 기록을 처리한다.</td></tr><tr><td>퇴근하기</td><td>선택된 기록에 <code>work_intime</code>은 있고 <code>work_outtime</code>은 없으면 표시한다. 퇴근 요청은 같은 선택 근무일의 기록을 처리한다.</td></tr><tr><td>근무 완료</td><td>선택된 기록에 <code>work_outtime</code>이 있으면 완료 상태로 표시하고 출퇴근 동작을 비활성화한다.</td></tr></tbody></table><p>대상 기록이 여러 건이면 <code>work_date</code> 오름차순으로 정렬한 뒤 퇴근 처리(<code>work_outtime</code>)가 되지 않은 가장 앞선 기록을 선택한다. 퇴근 처리 후 세션을 다시 조회하므로 다음 미퇴근 근무일이 선택된다. 미퇴근 기록이 없으면 가장 마지막 <code>work_date</code>를 표시하고 근무 완료 상태로 처리한다. 선택된 기록의 근무지를 위치 확인에 사용한다.</p><h3 id="_2-3-안전교육" tabindex="-1">2.3 안전교육 <a class="header-anchor" href="#_2-3-안전교육" aria-label="Permalink to &quot;2.3 안전교육&quot;">​</a></h3><ul><li>교육 제목과 재생 가능한 영상 링크를 등록한다.</li><li>직원별 전체·이수·미이수 건수를 확인한다.</li><li>미이수 알림 발송 전 대상 인원과 구독 상태를 확인한다.</li><li>자동 발송 실패 시 실행 이력의 오류 사유를 확인하고 수동 발송을 검토한다.</li></ul><h4 id="_2-3-1-월별-교육이수율-집계-기준" tabindex="-1">2.3.1 월별 교육이수율 집계 기준 <a class="header-anchor" href="#_2-3-1-월별-교육이수율-집계-기준" aria-label="Permalink to &quot;2.3.1 월별 교육이수율 집계 기준&quot;">​</a></h4><p><strong>월별교육이수</strong>(<code>/manager/safety/monthly_edu</code>)의 조회년월을 기준으로 월간·분기·반기 교육과 일일교육 이수 현황을 집계한다.</p><ul><li>월간 현황의 직원 대상은 <code>work_record</code>에서 실제 출근일시(<code>work_intime</code>)가 있고, 실제 출근일시 또는 예정 퇴근일시(<code>outtime</code>)가 조회월에 속하는 근무기록에 포함된 직원이다.</li><li>월간·분기·반기 교육은 직원 ID와 교육유형이 일치하는 <code>education_completions</code> 자료의 <code>work_date</code>가 해당 기간 안에 있고, 완료일시(<code>completed_at</code>)가 기록된 자료가 1건 이상이면 이수로 처리한다.</li></ul><table tabindex="0"><thead><tr><th>구분</th><th>조회월을 기준으로 하는 기간</th></tr></thead><tbody><tr><td>월간</td><td>조회월 1일부터 말일까지</td></tr><tr><td>분기</td><td>조회월이 속한 분기의 첫 달 1일부터 마지막 달 말일까지</td></tr><tr><td>반기</td><td>조회월이 속한 상반기(1월 1일~6월 30일) 또는 하반기(7월 1일~12월 31일) 전체</td></tr></tbody></table><p>예를 들어 조회년월이 2026년 9월이면 월간은 9월 1일~30일, 분기는 3분기인 7월 1일~9월 30일, 반기는 하반기인 7월 1일~12월 31일의 완료자료를 확인한다. 각 기간의 교육은 해당 기간 내 완료자료가 한 건 이상이면 이수이며, 그 외에는 미이수다.</p><p>월별 화면 아래의 <strong>월별 일일교육이수 기록</strong>은 <code>work_record</code>의 근무일(<code>work_date</code>)이 조회월에 속하고 실제 출근일시가 있는 직원·근무일을 대상으로 한다. 같은 직원과 근무일에 대한 일일교육 완료자료의 <code>completed_at</code>이 있으면 <code>O</code>, 없으면 <code>X</code>로 표시한다. 직원·근무일 조합은 한 건으로 집계한다.</p><p>화면 상단의 이수율은 월간·분기·반기 상태와 일일교육 근무일별 상태를 합산한다. 분모는 월간 현황 직원 수의 3배에 일일교육 대상 근무일 수를 더한 값이고, 분자는 이수로 판정된 항목 수다. 백분율은 소수점 이하를 반올림하며, 이름 검색을 사용하면 검색 결과에 해당하는 항목만 분자와 분모에 포함한다.</p><h3 id="_2-4-점검과-특이사항" tabindex="-1">2.4 점검과 특이사항 <a class="header-anchor" href="#_2-4-점검과-특이사항" aria-label="Permalink to &quot;2.4 점검과 특이사항&quot;">​</a></h3><ul><li>점검 현장은 근무지와 현장명만 등록한다. 현장 주소와 현장 GPS는 입력하거나 저장하지 않는다. 점검 이력의 좌표 스냅샷은 연결된 근무지 GPS를 사용하며, 등록된 현장의 QR/NFC 정보를 생성해 사용한다.</li><li>점검 이력은 최신 순으로 확인하고 필요 시 근무지로 필터링한다.</li><li>특이사항 보고의 내용, 사진, 위치와 Naver mail 전달 상태를 확인한다.</li><li>보고 삭제 시 연결 사진도 함께 삭제되므로 대상 내용을 다시 확인한다.</li></ul><h2 id="_3-정기-점검" tabindex="-1">3. 정기 점검 <a class="header-anchor" href="#_3-정기-점검" aria-label="Permalink to &quot;3. 정기 점검&quot;">​</a></h2><table tabindex="0"><thead><tr><th>주기</th><th>점검 항목</th></tr></thead><tbody><tr><td>매일</td><td>관리자 로그인, 주요 화면, 오류 로그, 교육 알림 결과</td></tr><tr><td>매주</td><td>미처리 특이사항, 실패 메일·푸시, 비정상 근태 데이터</td></tr><tr><td>매월</td><td>관리자 계정, DB 용량, Storage 용량, 외부 서비스 사용량</td></tr><tr><td>분기</td><td>키 교체 필요성, 백업 복구 훈련, 브라우저·모바일 호환성</td></tr></tbody></table><h2 id="_4-장애-대응" tabindex="-1">4. 장애 대응 <a class="header-anchor" href="#_4-장애-대응" aria-label="Permalink to &quot;4. 장애 대응&quot;">​</a></h2><ol><li>발생 시각, 사용자, 화면, 재현 절차와 오류 문구를 확보한다.</li><li>전체 장애인지 특정 사용자·기기·근무지 문제인지 구분한다.</li><li>Vercel 로그, Supabase 상태와 외부 서비스 상태를 확인한다.</li><li>데이터 손상 가능성이 있으면 쓰기 작업을 제한하고 백업을 확보한다.</li><li>복구 후 원인, 영향, 조치, 재발 방지 내용을 기록한다.</li></ol><h2 id="_5-주요-문제-해결" tabindex="-1">5. 주요 문제 해결 <a class="header-anchor" href="#_5-주요-문제-해결" aria-label="Permalink to &quot;5. 주요 문제 해결&quot;">​</a></h2><table tabindex="0"><thead><tr><th>증상</th><th>확인 순서</th></tr></thead><tbody><tr><td>관리자 로그인 실패</td><td>Supabase Auth, 관리자 등록, 콜백 URL, 쿠키</td></tr><tr><td>근무자 로그인 실패</td><td>이름·연락처, 전화번호 정규화, 퇴직 상태</td></tr><tr><td>출근 불가</td><td>당일 배정, 위치 권한, GPS 정확도, 인정 반경</td></tr><tr><td>교육 영상 재생 불가</td><td>영상 URL, 외부 공개 상태, 브라우저 네트워크</td></tr><tr><td>푸시 미수신</td><td>알림 권한, 구독 정보, VAPID 키, 실행 이력</td></tr><tr><td>메일 전송 실패</td><td>Naver SMTP 계정·비밀번호·포트, 수신 주소</td></tr><tr><td>지도 표시 실패</td><td>Kakao 키, 허용 도메인, 주소·좌표 값</td></tr></tbody></table><h2 id="_6-백업과-개인정보" tabindex="-1">6. 백업과 개인정보 <a class="header-anchor" href="#_6-백업과-개인정보" aria-label="Permalink to &quot;6. 백업과 개인정보&quot;">​</a></h2><ul><li>Supabase 백업 정책과 복구 가능 기간을 정기적으로 확인한다.</li><li>복구 훈련 시 별도 환경에서 데이터 정합성을 검증한다.</li><li>연락처, 위치, 사진은 업무 목적 범위에서만 조회·보관한다.</li><li>불필요해진 개인정보와 접근 권한은 내부 보존 정책에 따라 정리한다.</li></ul><h2 id="_7-문의-접수-기준" tabindex="-1">7. 문의 접수 기준 <a class="header-anchor" href="#_7-문의-접수-기준" aria-label="Permalink to &quot;7. 문의 접수 기준&quot;">​</a></h2><ul><li>접수 내용에는 사용자 구분, 발생 시각, 화면명, 기기·브라우저, 재현 절차를 포함한다.</li><li>개인정보와 인증정보가 포함된 화면은 필요한 부분만 마스킹하여 전달한다.</li><li>긴급도는 서비스 중단, 데이터 손실·보안, 주요 기능 장애, 일반 문의 순으로 분류한다.</li></ul><h2 id="_8-로그인-세션-관리-안내" tabindex="-1">8. 로그인 세션 관리 안내 <a class="header-anchor" href="#_8-로그인-세션-관리-안내" aria-label="Permalink to &quot;8. 로그인 세션 관리 안내&quot;">​</a></h2><h3 id="_8-1-로그인-방법" tabindex="-1">8.1 로그인 방법 <a class="header-anchor" href="#_8-1-로그인-방법" aria-label="Permalink to &quot;8.1 로그인 방법&quot;">​</a></h3><table tabindex="0"><thead><tr><th>구분</th><th>로그인 방법</th></tr></thead><tbody><tr><td>근무자</td><td>이름과 연락처로 로그인</td></tr><tr><td>관리자</td><td>등록된 Google 계정으로 로그인</td></tr></tbody></table><p>등록되지 않았거나 이용 권한이 없는 사용자는 로그인할 수 없다.</p><h3 id="_8-2-로그인은-얼마나-유지되나요" tabindex="-1">8.2 로그인은 얼마나 유지되나요? <a class="header-anchor" href="#_8-2-로그인은-얼마나-유지되나요" aria-label="Permalink to &quot;8.2 로그인은 얼마나 유지되나요?&quot;">​</a></h3><p>근무자와 관리자 모두 브라우저나 탭을 닫아도 로그인 상태가 유지된다. 같은 브라우저에서 다시 접속하면 별도의 로그인 없이 이전 화면을 계속 이용할 수 있다.</p><p>로그인 상태에는 정해진 만료 시간을 두지 않는다. 다만 다음 조건이 모두 충족되어야 자동 로그인이 유지된다.</p><ul><li>브라우저에 로그인 정보가 남아 있어야 한다.</li><li>근무자 또는 관리자 권한이 계속 유효해야 한다.</li><li>인증 정보에 보안상 문제가 없어야 한다.</li></ul><p>접속할 때마다 현재 이용 권한을 확인하고, 근무자의 배정 근무지와 근태 정보도 최신 내용으로 갱신한다.</p><h3 id="_8-3-언제-다시-로그인해야-하나요" tabindex="-1">8.3 언제 다시 로그인해야 하나요? <a class="header-anchor" href="#_8-3-언제-다시-로그인해야-하나요" aria-label="Permalink to &quot;8.3 언제 다시 로그인해야 하나요?&quot;">​</a></h3><p>다음과 같은 경우에는 로그인 화면이 다시 나타날 수 있다.</p><ul><li>사용자가 직접 로그아웃한 경우</li><li>브라우저의 쿠키나 사이트 데이터를 삭제한 경우</li><li>시크릿 모드를 종료한 경우</li><li>다른 기기 또는 관리 기능에서 인증이 해제된 경우</li><li>저장된 로그인 정보가 손상되었거나 보안상 사용할 수 없게 된 경우</li></ul><p>인터넷 연결이 일시적으로 끊어진 경우에는 저장된 로그인 정보를 바로 삭제하지 않는다. 연결이 복구되면 다시 접속하여 이용 권한을 확인한다.</p><h3 id="_8-4-퇴직·삭제·권한-회수-시에는-어떻게-되나요" tabindex="-1">8.4 퇴직·삭제·권한 회수 시에는 어떻게 되나요? <a class="header-anchor" href="#_8-4-퇴직·삭제·권한-회수-시에는-어떻게-되나요" aria-label="Permalink to &quot;8.4 퇴직·삭제·권한 회수 시에는 어떻게 되나요?&quot;">​</a></h3><p>로그인 상태가 남아 있어도 현재 이용 권한이 없으면 시스템을 사용할 수 없다.</p><table tabindex="0"><thead><tr><th>상황</th><th>처리 결과</th></tr></thead><tbody><tr><td>근무자가 퇴직 처리되거나 삭제됨</td><td>근무자 화면과 업무 기능 이용 차단</td></tr><tr><td>관리자가 삭제되거나 권한이 회수됨</td><td>관리자 화면과 관리 기능 이용 차단</td></tr><tr><td>권한이 다시 부여됨</td><td>보안을 위해 다시 로그인</td></tr></tbody></table><p>근무자의 경우 이용할 수 없는 상태가 확인되면 저장된 로그인 정보를 지우고 로그인 화면으로 이동한다. 관리자는 등록된 관리자 권한이 확인되지 않으면 관리자 화면에 들어갈 수 없다.</p><h3 id="_8-5-로그아웃하면-어떻게-되나요" tabindex="-1">8.5 로그아웃하면 어떻게 되나요? <a class="header-anchor" href="#_8-5-로그아웃하면-어떻게-되나요" aria-label="Permalink to &quot;8.5 로그아웃하면 어떻게 되나요?&quot;">​</a></h3><p>근무자가 로그아웃하면 저장된 로그인 정보와 알림 연결 정보를 정리한 후 근무자 로그인 화면으로 이동한다.</p><p>관리자가 로그아웃하면 관리자 인증을 종료한 후 관리자 로그인 화면으로 이동한다.</p><p>공용 PC나 다른 사람과 함께 사용하는 기기에서는 브라우저만 닫지 말고 반드시 <strong>로그아웃</strong>해야 한다.</p><h3 id="_8-6-자동-로그인이-되지-않을-때" tabindex="-1">8.6 자동 로그인이 되지 않을 때 <a class="header-anchor" href="#_8-6-자동-로그인이-되지-않을-때" aria-label="Permalink to &quot;8.6 자동 로그인이 되지 않을 때&quot;">​</a></h3><p>다음 사항을 순서대로 확인한다.</p><ol><li>인터넷 연결을 확인하고 다시 접속한다.</li><li>올바른 이름·연락처 또는 등록된 Google 계정을 사용했는지 확인한다.</li><li>브라우저에서 쿠키와 사이트 데이터 저장이 차단되어 있지 않은지 확인한다.</li><li>퇴직, 계정 삭제 또는 권한 회수 여부를 관리자에게 문의한다.</li></ol><p>문제가 계속되면 관리자에게 사용자 이름, 접속 시각 및 화면에 표시된 안내 문구를 전달한다.</p>',80)])])}const u=d(r,[["render",l]]);export{s as __pageData,u as default};
